const result = $input.first().json;
const offers = result.offers || [];
const CHAT_ID = $env.TELEGRAM_HUNTER_CHAT_ID;
const HIGH_THRESHOLD = 80.0;

const messages = [];

const highOffers = offers.filter(o => parseFloat(o.match_rate) >= HIGH_THRESHOLD);
for (const offer of highOffers) {
  const rate = parseFloat(offer.match_rate);
  const skills = (offer.skills_found || '').trim();
  const skillsLine = skills ? '\nSkills : ' + skills : '';
  const text = '🎯 *' + offer.title + '* — ' + offer.company +
    '\n📍 ' + offer.location +
    '\n🔗 ' + offer.url +
    '\n\n*Match* : ' + rate + '%' + skillsLine;
  messages.push({
    json: {
      type: 'card',
      telegram_payload: {
        chat_id: CHAT_ID,
        text,
        parse_mode: 'Markdown',
        reply_markup: {
          inline_keyboard: [[
            { text: '✅ Générer', callback_data: 'hunter:gen:' + offer.job_id },
            { text: '⏰ Snooze', callback_data: 'hunter:snooze:' + offer.job_id },
            { text: '❌ Ignorer', callback_data: 'hunter:ignore:' + offer.job_id }
          ]]
        }
      }
    }
  });
}

const lowOffers = offers.filter(o => {
  const r = parseFloat(o.match_rate);
  return r >= 60.0 && r < HIGH_THRESHOLD;
});
if (lowOffers.length > 0) {
  const lines = lowOffers.map(o => '• ' + o.match_rate + '% — *' + o.title + '* @ ' + o.company);
  const text = '📋 *Digest du jour — ' + lowOffers.length + ' offre' + (lowOffers.length > 1 ? 's' : '') + '*\n\n' + lines.join('\n');
  messages.push({
    json: {
      type: 'digest',
      telegram_payload: {
        chat_id: CHAT_ID,
        text,
        parse_mode: 'Markdown'
      }
    }
  });
}

return messages;
